from __future__ import annotations

import base64
import gzip
import hashlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
AUTHORING = ROOT / "app" / "admin_authoring_v4.py"
ENTRY = ROOT / "app" / "runtime_entry.py"
GOOGLE_API = ROOT / "app" / "google_api.py"
ADMIN_CONSOLE = ROOT / "app" / "admin_console.py"
EXPECTED_SHA256 = "e0ed357a1b03c19ffc5be935d6d5fdb5f6a1d367654481a08739b76b595c71ea"

PAYLOAD = (
""
""
""
)


def _patch_google_scopes() -> None:
    source = GOOGLE_API.read_text(encoding="utf-8")
    source = source.replace(
        '"https://www.googleapis.com/auth/drive.readonly",',
        '"https://www.googleapis.com/auth/drive.file",\n'
        '    "https://www.googleapis.com/auth/documents",\n'
        '    "https://www.googleapis.com/auth/presentations",\n'
        '    "https://www.googleapis.com/auth/spreadsheets",\n'
        '    "https://www.googleapis.com/auth/forms.body",',
    )
    GOOGLE_API.write_text(source, encoding="utf-8")


def _patch_admin_navigation() -> None:
    source = ADMIN_CONSOLE.read_text(encoding="utf-8")
    needle = '<a href="/admin/courses">Cursos</a>'
    replacement = needle + '<a href="/admin/authoring">Course Studio</a>'
    if replacement not in source:
        source = source.replace(needle, replacement)
    ADMIN_CONSOLE.write_text(source, encoding="utf-8")


def _register_runtime() -> None:
    source = ENTRY.read_text(encoding="utf-8")
    markers = (
        "# NEXUS_AUTHORING_STUDIO_V2",
        "# NEXUS_AUTHORING_STUDIO_V3",
        "# NEXUS_AUTHORING_STUDIO_V4",
        "# NEXUS_AUTHORING_STUDIO_V5",
    )
    lines = source.splitlines()
    cleaned: list[str] = []
    skip = 0
    for line in lines:
        if any(line.strip() == marker for marker in markers):
            skip = 3
            continue
        if skip:
            skip -= 1
            continue
        cleaned.append(line)
    source = "\n".join(cleaned).rstrip() + (
        "\n\n# NEXUS_AUTHORING_STUDIO_V5\n"
        "from app.admin_authoring_v4 import register_authoring_v4\n"
        "register_authoring_v4(app)\n"
    )
    ENTRY.write_text(source, encoding="utf-8")


def main() -> None:
    raw = gzip.decompress(base64.b64decode(PAYLOAD))
    digest = hashlib.sha256(raw).hexdigest()
    if digest != EXPECTED_SHA256:
        raise RuntimeError(f"Course Studio V5 incompleto: {digest}")
    AUTHORING.write_bytes(raw)
    _patch_google_scopes()
    _patch_admin_navigation()
    _register_runtime()
    compile(AUTHORING.read_text(encoding="utf-8"), str(AUTHORING), "exec")
    print("NEXUS Course Studio V5 aplicado: Google Workspace, OpenDocument, IA, AR y VR.")


if __name__ == "__main__":
    main()
